@import url('https://fonts.googleapis.com/css2?family=Varela+Round&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Arc DNA — soft pastel gradients, macOS-glass panels, bubbly corners */
.theme-arc-dna {
  --bg: oklch(0.989 0.024 99.1);
  --surface: oklch(1 0 0 / 62%);
  --surface-2: oklch(1 0 0 / 42%);
  --fg: oklch(0.25 0.04 300);
  --fg-muted: oklch(0.5 0.04 300);
  --accent: oklch(0.499 0.274 269.3);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.68 0.15 240);
  --line: oklch(1 0 0 / 55%);
  --success: oklch(0.7 0.14 155);
  --warning: oklch(0.817 0.164 75.9);
  --danger: oklch(0.650 0.226 21.5);

  --radius: 1.125rem;
  --radius-sm: 0.75rem;
  --radius-lg: 1.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0.3 0.05 300 / 8%), inset 0 1px 0 oklch(1 0 0 / 60%);
  --shadow-2: 0 12px 32px -12px oklch(0.35 0.08 300 / 28%), inset 0 1px 0 oklch(1 0 0 / 65%);
  --shadow-3: 0 30px 70px -28px oklch(0.35 0.08 300 / 38%);
  --glow: 0 0 0 4px color-mix(in oklab, var(--accent) 25%, transparent);

  --border-width: 1px;
  --blur-amount: 24px;

  --font-display: "Varela Round", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.025em;
  --label-transform: none;
  --label-tracking: 0.01em;

  background-color: var(--bg);
  background-image:
    radial-gradient(55% 50% at 10% 5%, oklch(0.88 0.11 330 / 85%), transparent 70%),
    radial-gradient(50% 45% at 90% 15%, oklch(0.88 0.1 250 / 75%), transparent 70%),
    radial-gradient(60% 50% at 60% 95%, oklch(0.9 0.1 190 / 70%), transparent 70%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-arc-dna h1,
.theme-arc-dna h2,
.theme-arc-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

.theme-arc-dna section > div,
.theme-arc-dna article,
.theme-arc-dna dialog {
  backdrop-filter: blur(var(--blur-amount)) saturate(160%);
  -webkit-backdrop-filter: blur(var(--blur-amount)) saturate(160%);
}

/* signature */
.theme-arc-dna { background-image: radial-gradient(circle at 15% 12%, oklch(0.9 0.06 300 / 45%), transparent 35%), radial-gradient(circle at 85% 25%, oklch(0.9 0.05 220 / 40%), transparent 35%); }
.theme-arc-dna { --font-ui: var(--font-display); }
.theme-arc-dna button { transition: transform 160ms cubic-bezier(0.34, 1.56, 0.64, 1); }
.theme-arc-dna button:hover { transform: scale(1.05) rotate(-0.5deg); }

/* depth */
.theme-arc-dna input, .theme-arc-dna select, .theme-arc-dna textarea { background: oklch(1 0 0 / 55%); border: 1px solid oklch(1 0 0 / 70%); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); transition: background 160ms ease, box-shadow 160ms ease; }
.theme-arc-dna input:focus-visible, .theme-arc-dna select:focus-visible, .theme-arc-dna textarea:focus-visible { outline: none; background: oklch(1 0 0 / 80%); box-shadow: var(--glow); }
.theme-arc-dna thead th { font-size: 0.72rem; font-weight: 700; color: var(--fg-muted); border-bottom: 1px solid oklch(1 0 0 / 60%); }
.theme-arc-dna td { border-bottom: 1px solid oklch(1 0 0 / 40%); }
.theme-arc-dna tbody tr:hover { background: oklch(1 0 0 / 50%); }
.theme-arc-dna a { color: var(--accent); text-decoration: none; border-bottom: 2px solid color-mix(in oklab, var(--accent) 35%, transparent); transition: border-color 160ms ease; }
.theme-arc-dna a:hover { border-bottom-color: var(--accent); }
.theme-arc-dna kbd { background: oklch(1 0 0 / 75%); border: 1px solid oklch(1 0 0 / 85%); border-radius: 0.5em; box-shadow: 0 2px 0 oklch(0.3 0.05 300 / 15%); padding: 0.1em 0.45em; font-size: 0.78em; }
.theme-arc-dna ::selection { background: oklch(0.88 0.11 330 / 70%); }
.theme-arc-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-arc-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-arc-dna ::-webkit-scrollbar-thumb { background: oklch(0.6 0.08 300 / 40%); border-radius: 999px; border: 3px solid transparent; background-clip: padding-box; }
.theme-arc-dna button:active { transform: scale(0.94); }
.theme-arc-dna .label-caps { color: var(--fg-muted); font-weight: 700; }
.theme-arc-dna .themed-border { border-color: oklch(1 0 0 / 75%); box-shadow: var(--shadow-2); }

/* alt mode: dusk variant — the same pastel glow after sunset */
.theme-arc-dna.alt-mode {
  --bg: oklch(0.215 0.045 300);
  --surface: oklch(0.34 0.05 300 / 55%);
  --surface-2: oklch(0.38 0.05 300 / 40%);
  --fg: oklch(0.965 0.010 300);
  --fg-muted: oklch(0.760 0.030 300);
  --line: oklch(1 0 0 / 20%);
  --accent: oklch(0.664 0.150 269.3);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%), inset 0 1px 0 oklch(1 0 0 / 12%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%), inset 0 1px 0 oklch(1 0 0 / 14%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image:
    radial-gradient(55% 50% at 10% 5%, oklch(0.45 0.12 330 / 70%), transparent 70%),
    radial-gradient(50% 45% at 90% 15%, oklch(0.42 0.11 250 / 60%), transparent 70%),
    radial-gradient(60% 50% at 60% 95%, oklch(0.42 0.10 190 / 55%), transparent 70%);
  background-attachment: fixed;
}

.theme-arc-dna.alt-mode input,
.theme-arc-dna.alt-mode select,
.theme-arc-dna.alt-mode textarea { background: oklch(0.3 0.05 300 / 60%); border-color: oklch(1 0 0 / 22%); }
.theme-arc-dna.alt-mode input:focus-visible,
.theme-arc-dna.alt-mode select:focus-visible,
.theme-arc-dna.alt-mode textarea:focus-visible { background: oklch(0.34 0.05 300 / 80%); }
.theme-arc-dna.alt-mode kbd { background: oklch(0.36 0.05 300 / 80%); border-color: oklch(1 0 0 / 25%); box-shadow: 0 2px 0 oklch(0 0 0 / 40%); }
.theme-arc-dna.alt-mode thead th { border-bottom-color: oklch(1 0 0 / 25%); }
.theme-arc-dna.alt-mode td { border-bottom-color: oklch(1 0 0 / 14%); }
.theme-arc-dna.alt-mode tbody tr:hover { background: oklch(1 0 0 / 10%); }
.theme-arc-dna.alt-mode .themed-border { border-color: oklch(1 0 0 / 25%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
